import { Media } from "@parksandresorts/webapiproxy-types";
import { Variants } from "framer-motion";
import styles from "./grid-media-item.module.less";
import StyledRadioButtons from "@/core/components/primitives/styled-radio-buttons/styled-radio-buttons";
import { useEffect, useState } from "react";
import { SkeletonRectangle } from "@/core/components/primitives/skeleton-rectangle/skeleton-rectangle";
import Icon from "@/core/components/primitives/icon/icon";
import { useTranslation } from "react-i18next";
import { EventAggregator, multipleClassNames } from "@/core/helpers";
import { AnimatedFerrisWheel } from "@/core/components/primitives/animated-ferris-wheel/animated-ferris-wheel";
import Card from "@/core/components/primitives/card/card";

type Props = {
  media: Media;
  isHighlighted: boolean;
  mode: "normal" | "selecting";
  type?: "real" | "placeholderVideo";
  hasBeenSelected?: boolean;
  isBeingRemoved?: boolean;
  onClick: () => void;
};

const mediaItemVariants = {
  default: {
    opacity: 1,
  },
  notSelected: {
    opacity: 0.35,
  },
} satisfies Variants;

const hoverEffect = {
  scale: 1.05,
  transition: { delay: 0 },
};

const tapEffect = {
  scale: 0.95,
  transition: { delay: 0 },
};

export const GridMediaItem = ({
  media,
  isHighlighted,
  onClick,
  mode,
  type = "real",
  hasBeenSelected,
  isBeingRemoved,
}: Props) => {
  const { t } = useTranslation();
  const [hasLoaded, setHasLoaded] = useState(false);
  const [failedLoading, setFailedLoading] = useState(false);

  const shouldRenderNotSelected = mode === "selecting" && !hasBeenSelected;

  //Loop three ellipses "..." between 0-3 dots
  const [dots, setDots] = useState("");
  useEffect(() => {
    if (type !== "placeholderVideo") {
      return undefined;
    }
    const interval = setInterval(() => {
      setDots((prev) => (prev.length < 3 ? prev + "." : ""));
    }, 750);
    return () => clearInterval(interval);
  }, [type]);

  if (type === "placeholderVideo") {
    return (
      <>
        <Card
          id={`placeholder-${media.mediaId}-video`}
          className={multipleClassNames(styles.mediaItem, styles.placeholderItem)}
          whileHover={hoverEffect}
          whileTap={tapEffect}
          onClick={onClick}
          data-testid={`placeholder-${media.referenceNumber}-video`}
        >
          <div className={styles.ferrisWheelWrapper}>
            <AnimatedFerrisWheel />
          </div>
          <div className={styles.placeholderContent}>
            <strong>{`${t("rideMediaAlbumPlaceholderVideoText")}${dots}`}</strong>
          </div>
        </Card>
      </>
    );
  }

  return (
    <Card
      id={`media-${media.mediaId}`}
      className={styles.mediaItem}
      animate={shouldRenderNotSelected ? "notSelected" : "default"}
      variants={mediaItemVariants}
      whileHover={hoverEffect}
      whileTap={tapEffect}
      data-has-loaded={hasLoaded}
      data-failed-loading={failedLoading}
      onClick={onClick}
    >
      {mode === "selecting" && (
        <div className={styles.radio}>
          <StyledRadioButtons
            name={`radio-media-${media.mediaId}`}
            value={hasBeenSelected ? `selected-${media.mediaId}` : `not-selected-${media.mediaId}`}
            options={[{ label: "", value: `selected-${media.mediaId}` }]}
            onChange={() => {
              // Do nothing. onClick is handled on the parent div
            }}
          />
        </div>
      )}
      {isBeingRemoved && (
        <div className={styles.beingRemovedOverlay}>
          <p>{t("removing")}</p> <Icon name="loading" />
        </div>
      )}
      {!hasLoaded && !failedLoading && <SkeletonRectangle />}
      {failedLoading && (
        <div className={styles.errorIcon}>
          <Icon name="error" />
        </div>
      )}
      {media.mediaType === "Video" && (
        <div className={styles.playIcon}>
          <Icon name="play" />
        </div>
      )}
      <img
        src={media.smallUrl}
        alt="Media"
        data-is-highlighted={isHighlighted}
        data-testid={`grid-media-item-${media.mediaId}`}
        onLoad={() => {
          setHasLoaded(true);
        }}
        onError={() => {
          EventAggregator.publish("trackEvent", {
            category: "Digital Ride Media - Failed to load media",
            action: `time: ${new Date().getTime()} mediaId:${media.mediaId} mediaType:${media.mediaType}`,
            label: media.smallUrl,
          });
          setFailedLoading(true);
        }}
      />
    </Card>
  );
};
