/** Make sure the media items are within the correct grid (due to animation both grids are in the DOM) */
const mediaIsWithinGrid = async ({
  canvasElement,
  gridTestId,
  mediaTestIds,
}: {
  canvasElement: HTMLElement;
  gridTestId: string;
  mediaTestIds: string[];
}) => {
  const canvas = within(canvasElement);
  await waitFor(
    () => {
      const grid = canvas.getByTestId(gridTestId);
      for (const id of mediaTestIds) {
        const media = canvas.getByTestId(id);
        expect(grid).toContainElement(media);
      }
    },
    { timeout: 5000 },
  );
};

