export const WithVideoPendingAndThenLoaded: Story = {
  args: {
    ...EmptyAlbum.args,
    albumId: "KOL-TOD-PEN-VID",
    hasPendingVideo: true,
    loadPendingVideo: true,
    // Overwritten function to simulate video loading after being pending, by returning the video in the second call to fetchAlbumMedia.
    createServiceOverride: () => {
      const albumWithPending = allAppAlbumsById["KOL-TOD-PEN-VID"];
      const albumWithVideo = allAppAlbumsById["KOL-TOD-VID-LOA"];
      let fetchCount = 0;
      return {
        fetchAlbumMedia: async (_albumId) => {
          await delay(1000);
          fetchCount++;
          console.log(`fetchAlbumMedia called ${fetchCount} times`);
          // Show album with pending video
          if (fetchCount === 1) {
            return { album: albumWithPending.album, media: albumWithPending.media };
          }
          // Show album with loaded video
          return { album: albumWithVideo.album, media: albumWithVideo.media };
        },
      };
    },
  },
  play: async ({ canvasElement }) => {
    // Placeholder is shown while video is pending
    await waitForVisibleElement({
      canvasElement,
      testId: "grid-media-item-01234-0004-0000",
    });
    // Wait for the video to load and replace the placeholder.
    // We poll every 10 seconds, so increased timout since the test is sometimes slower than that.
    await waitForVisibleElement({
      canvasElement,
      testId: "grid-media-item-01234-0004-1111",
      timeout: 12_000,
    });
    await elementIsNotInDocument({
      canvasElement,
      testIds: ["placeholder-01234-0004-1111"],
    });
  },
};

