/**
 * Selecting individual media until the combined price reaches the album price automatically upgrades
 * the purchase to the whole album: the CTA switches, and a helper text explains why & celebratory confetti.
 */
export const WithPurchaseConvertedToAlbum: Story = {
  args: {
    ...EmptyAlbum.args,
    albumId: "KOL-TOD-NON-MAN",
  },
  play: async ({ canvasElement }) => {
    await waitForVisibleElement({
      canvasElement,
      testId: "digital-ride-media-album-locked-media-grid",
    });

    // Enter "select media to buy" mode.
    await clickOnElement({
      canvasElement,
      testId: "digital-ride-media-album-start-purchasing-media-button",
    });

    // Select two photos (60 + 60 = 120 kr) – still below the album price (150), so no conversion yet.
    await clickOnElement({ canvasElement, testId: "grid-media-item-01234-0001-0000" });
    await clickOnElement({ canvasElement, testId: "grid-media-item-01234-0003-0000" });
    await waitForVisibleElement({
      canvasElement,
      testId: "digital-ride-media-album-purchase-selected-media-button",
    });
    await elementIsNotInDocument({
      canvasElement,
      testIds: ["digital-ride-media-album-purchase-converted-to-album-button"],
    });

    // Add the video (+60 = 180 kr) – now at/over the album price, so we convert to the album.
    await clickOnElement({ canvasElement, testId: "grid-media-item-01234-0004-1111" });
    await waitForVisibleElement({
      canvasElement,
      testId: "digital-ride-media-album-reached-album-price-helper",
    });
    await waitForVisibleElement({
      canvasElement,
      testId: "digital-ride-media-album-purchase-converted-to-album-button",
    });
  },
};

/**
 * The customer already bought one photo (60 kr) earlier. One more photo isn't enough to reach the
 * album price (60 + 60 = 120 < 150), so no upgrade yet. Adding a second one (180 kr total) finally passes it,
 * triggering the upgrade and the discount helper — they only pay the difference (90 kr).
 */
export const WithPurchaseConvertedToAlbumDiscount: Story = {
  args: {
    ...EmptyAlbum.args,
    albumId: "KOL-TOD-UPG-ONE",
    seedPurchasedMediaIds: ["01234-0002-0000"],
  },
  play: async ({ canvasElement }) => {
    await mediaIsWithinGrid({
      canvasElement,
      gridTestId: "digital-ride-media-album-unlocked-media-grid",
      mediaTestIds: ["grid-media-item-01234-0002-0000"],
    });
    await clickOnElement({
      canvasElement,
      testId: "segmented-control-lockedOrUnlockedMedia-locked",
    });
    await waitForVisibleElement({
      canvasElement,
      testId: "digital-ride-media-album-locked-media-grid",
    });
    await clickOnElement({
      canvasElement,
      testId: "digital-ride-media-album-start-purchasing-media-button",
    });

    // Select one photo (60 kr): combined with the 60 kr already spent that's only 120 kr – still below the
    // album price, so the normal "select media" helper stays and no upgrade happens yet.
    await clickOnElement({ canvasElement, testId: "grid-media-item-01234-0001-0000" });
    await waitForVisibleElement({
      canvasElement,
      testId: "digital-ride-media-album-purchase-selected-media-button",
    });
    await elementIsNotInDocument({
      canvasElement,
      testIds: ["digital-ride-media-album-upgrade-discount-helper"],
    });

    // Select a second photo (+60 = 180 kr total) – now it passes the album price, so we convert to the album
    // and show the discount helper.
    await clickOnElement({ canvasElement, testId: "grid-media-item-01234-0003-0000" });
    await waitForVisibleElement({
      canvasElement,
      testId: "digital-ride-media-album-upgrade-discount-helper",
    });
    await waitForVisibleElement({
      canvasElement,
      testId: "digital-ride-media-album-purchase-converted-to-album-button",
    });
  },
};

