import { Modal } from "@/core/components/primitives/modal/modal";
import { Media } from "@parksandresorts/webapiproxy-types";
import { GhostButton, OutlineButton, PrimaryButton } from "@/core/components/primitives/parks-button/parks-button";
import { useContentContainerRef } from "@/core/components/primitives/content-container/content-container";
import { DateHelper, multipleClassNames } from "@/core/helpers";
import styles from "./focused-media-modal.module.less";
import DropdownMenu from "@/core/components/primitives/dropdown-menu/dropdown-menu";
import { useCallback, useEffect, useMemo, useState } from "react";
import { useTranslation } from "react-i18next";
import { createFileFromMedia, downloadFile, getMediaFileNameAndMimeType, getTitleFromRideId } from "../../../helpers";
import { AnimatePresence, motion } from "framer-motion";
import { SkeletonRectangle } from "@/core/components/primitives/skeleton-rectangle/skeleton-rectangle";
import Icon from "@/core/components/primitives/icon/icon";
import { BrowserSupportHelper } from "@/core/helpers";

type Props = {
  isOpen: boolean;
  focusedMedia: Media;
  singleMediaPrice: number;
  onClose: () => void;
  removeMedia: (mediaId: string) => void;
  purchaseSingleMedia: (mediaId: string) => void;
};

export const FocusedMediaModal = ({
  isOpen,
  focusedMedia,
  singleMediaPrice,
  onClose,
  removeMedia,
  purchaseSingleMedia,
}: Props) => {
  const { t } = useTranslation();
  const [focusedMediaFile, setFocusedMediaFile] = useState<File>();
  const [showRemoveMediaConfirmation, setShowRemoveMediaConfirmation] = useState(false);
  const [hasLoaded, setHasLoaded] = useState(false);
  const [errorLoaded, setErrorLoaded] = useState(false);
  const wrapperElement = useContentContainerRef();

  const rideTitle = getTitleFromRideId(focusedMedia.attractionId);
  const { fileName } = getMediaFileNameAndMimeType(focusedMedia);

  useEffect(() => {
    const fetchMediaData = async () => {
      try {
        const file = await createFileFromMedia(focusedMedia);
        setFocusedMediaFile(file);
      } catch (e) {
        console.error("Failed to fetch media data", e);
        setErrorLoaded(true);
        setHasLoaded(true);
      }
    };
    fetchMediaData();
  }, []);

  const focusedMediaUrl = useMemo(() => {
    return focusedMediaFile && URL.createObjectURL(focusedMediaFile);
  }, [focusedMediaFile]);

  const shareFocusedMediaFile = async () => {
    const shareData = {
      //Remove file extension from title
      title: fileName.replace(/\.[^/.]+$/, ""),
      files: [focusedMediaFile as File],
    } satisfies ShareData;
    try {
      await navigator.share(shareData);
    } catch (err) {
      console.error("Error sharing:", err);
    }
  };

  const downloadMedia = useCallback(() => {
    if (focusedMediaUrl) {
      downloadFile(focusedMediaUrl, fileName);
    }
  }, [focusedMediaUrl, fileName]);

  const isiOS = useMemo(() => {
    return BrowserSupportHelper.getDeviceType() === "iOS";
  }, []);

  return (
    <Modal
      modalContentAnimation={{
        initial: { scale: 0 },
        animate: { scale: 1 },
        exit: { scale: 0, transition: { type: "tween", duration: 0.2 } },
        transition: { type: "spring", stiffness: 100, damping: 8 },
      }}
      isOpen={isOpen}
      onClose={onClose}
      innerClassName={styles.innerModal}
      refWrapperElement={wrapperElement ?? undefined}
    >
      {focusedMedia && (
        <div
          className={multipleClassNames(styles.modalContent, styles.imageModalContent)}
          data-has-loaded={hasLoaded}
          data-was-error={errorLoaded}
        >
          <div className={styles.imageModalHeading}>
            <p className="bold">{rideTitle || ""} </p>
            <GhostButton iconCenterNew="close" iconSize="xl" onClick={onClose} />
          </div>
          {!hasLoaded && <SkeletonRectangle />}
          {errorLoaded && (
            <div className={styles.error}>
              {t("somethingWentWrong")}
              <Icon name="error" />
            </div>
          )}
          {focusedMedia.mediaType === "Photo" && focusedMediaUrl && (
            <div className={styles.mediaWrapper} data-orientation={focusedMedia.orientation}>
              <div className={styles.mediaFrame}>
                <img
                  alt="Media"
                  src={focusedMediaUrl}
                  onLoad={() => {
                    setHasLoaded(true);
                  }}
                />
              </div>
            </div>
          )}
          {focusedMedia.mediaType === "Video" && (
            <div className={styles.mediaWrapper} data-orientation={focusedMedia.orientation}>
              <div className={styles.mediaFrame}>
                <video
                  controls
                  controlsList="nodownload"
                  playsInline
                  //t=0.1 is to force iOS to show the first frame before playing https://stackoverflow.com/a/65226419
                  src={`${focusedMedia.url!}#t=0.1`}
                  onLoadStart={() => {
                    setHasLoaded(true);
                  }}
                />
              </div>
            </div>
          )}
          <i className={multipleClassNames("body-xs", styles.metaData)}>
            {t("rideMediaAlbumMetaDataPrefix")} {DateHelper.toStringDDMMHHMM(new Date(focusedMedia.createTime))}
          </i>
          <AnimatePresence mode="popLayout">
            {focusedMedia.locked && !showRemoveMediaConfirmation && (
              <motion.div
                key="lockedImageModalButtonWrapper"
                className={styles.lockedImageModalButtonWrapper}
                animate={{ opacity: 1 }}
                exit={{ opacity: 0, transition: { duration: 0.2 } }}
              >
                <p className={multipleClassNames("bold", styles.priceTag)}>
                  {t("rideMediaAlbumPurchaseSinglePriceTag", { singleMediaPrice })}
                </p>
                <DropdownMenu
                  triggerButton={{
                    buttonType: "GhostButton",
                    iconSize: "xl",
                    iconCenterNew: "more-vertical",
                    className: styles.lockedImageMenuButton,
                  }}
                  itemGroups={[
                    {
                      items: [
                        {
                          label: t("rideMediaAlbumRemoveMediaMenuOption"),
                          rightSlot: { name: "trash" },
                          onClick: () => {
                            setShowRemoveMediaConfirmation(true);
                          },
                        },
                      ],
                    },
                  ]}
                />
                <PrimaryButton
                  isFullWidth
                  label={
                    focusedMedia.mediaType === "Photo"
                      ? t("rideMediaAlbumPurchaseSinglePhotoButtonText")
                      : t("rideMediaAlbumPurchaseSingleVideoButtonText")
                  }
                  className={styles.buyMediaButton}
                  onClick={() => purchaseSingleMedia(focusedMedia.mediaId)}
                />
              </motion.div>
            )}
            {focusedMedia.locked && showRemoveMediaConfirmation && (
              <motion.div
                key="removeMediaConfirmation"
                animate={{ opacity: 1 }}
                exit={{ opacity: 0, transition: { duration: 0.2 } }}
                className={styles.removeMediaConfirmation}
              >
                <p>{t("rideMediaAlbumRemoveMediaConfirmationParagraph")}</p>
                <div className={styles.imageModalButtonWrapper}>
                  <OutlineButton onClick={() => setShowRemoveMediaConfirmation(false)} isFullWidth label={t("no")} />
                  <PrimaryButton
                    onClick={() => {
                      removeMedia(focusedMedia.mediaId);
                      onClose();
                    }}
                    isFullWidth
                    label={t("yes")}
                  />
                </div>
              </motion.div>
            )}
          </AnimatePresence>
          {!focusedMedia.locked && (
            <div className={styles.imageModalButtonWrapper}>
              {!isiOS && (
                <>
                  <OutlineButton isFullWidth label={t("share")} iconLeftNew="share" onClick={shareFocusedMediaFile} />
                  <PrimaryButton
                    isFullWidth
                    isDisabled={!focusedMediaUrl}
                    label={focusedMediaUrl ? t("download") : t("rideMediaAlbumPreparingDownload")}
                    iconLeftNew={focusedMediaUrl ? "file-download" : "loading"}
                    onClick={downloadMedia}
                  />
                </>
              )}
              {/* On iOS, the download feature is not great since it wants to save the downloaded image/video in the "Files"-folder.
              We therefore only show the share button on iOS, since the share sheet that pops up has a better "save" option that puts the file in the camera roll. */}
              {isiOS && (
                <PrimaryButton
                  isFullWidth
                  label={
                    focusedMediaFile ? t("rideMediaAlbumiOSShareAndDownload") : t("rideMediaAlbumPreparingDownload")
                  }
                  iconLeftNew={focusedMediaFile ? "file-download" : "loading"}
                  onClick={shareFocusedMediaFile}
                />
              )}
            </div>
          )}
        </div>
      )}
    </Modal>
  );
};
