import { forwardRef, useEffect, useRef, useState } from "react";
import styles from "./album-header.module.less";
import { Album } from "@parksandresorts/webapiproxy-types";
import InputError from "@/core/components/primitives/input-error/input-error";
import InputField from "@/core/components/primitives/input-field/input-field";
import { SkeletonRectangle } from "@/core/components/primitives/skeleton-rectangle/skeleton-rectangle";
import { PrimaryButton } from "@/core/components/primitives/parks-button/parks-button";
import { AnimatePresence, motion } from "framer-motion";
import { useTranslation } from "react-i18next";
import DropdownMenu from "@/core/components/primitives/dropdown-menu/dropdown-menu";
import { DateHelper, multipleClassNames } from "@/core/helpers";
import Popover from "@/core/components/primitives/popover/popover";
import Icon from "@/core/components/primitives/icon/icon";
import { albumIdWithHyphens, expirationDuration } from "../../../helpers";
import { slideLeftWhenHiddenVariants } from "../animations";
import { BackButton } from "../../../elements/back-button/back-button";
import { useCopyToClipboard, useLocalStorage } from "@/core/hooks";

type Props = {
  albumId: string;
  album: Album | undefined;
  isLoadingAlbum: boolean;
  isAlbumInfoModalJustCreatedOpen: boolean;
  isErrorFetchingAlbum: boolean;
  updateName: (name: string) => void;
  resetNameChange: () => void;
  isPendingNameChange: boolean;
  isNameChangeSuccess: boolean;
  gotErrorUpdatingName: boolean;
  onShare: () => void;
  onBack: () => void;
  onDeleteAlbum: () => void;
  onLeaveAlbum: () => void;
  onHelp: () => void;
  onShowAlbumIdQrCode: () => void;
  onSendCodeToMe: () => void;
  onShowAlbumInfo: () => void;
};

const SOON_TO_EXPIRE_THRESHOLD_DAYS = 10;

export const ALBUM_HEADER_MENU_BUTTON_TEST_ID = "digital-ride-media-album-header-menu-button";

export const AlbumHeader = forwardRef<HTMLDivElement, Props>(
  (
    {
      albumId,
      album,
      isLoadingAlbum,
      isAlbumInfoModalJustCreatedOpen,
      isErrorFetchingAlbum,
      updateName,
      resetNameChange,
      isPendingNameChange,
      isNameChangeSuccess,
      gotErrorUpdatingName,
      onShare,
      onBack,
      onDeleteAlbum,
      onLeaveAlbum,
      onHelp,
      onShowAlbumIdQrCode,
      onSendCodeToMe,
      onShowAlbumInfo,
    }: Props,
    ref,
  ) => {
    const [isEditingName, setIsEditingName] = useState<boolean>(false);
    const [albumName, setAlbumName] = useState<string>("");
    const titleRef = useRef<HTMLHeadingElement>(null);
    const shareButtonRef = useRef<HTMLButtonElement>(null);

    const [hasSeenSharePopover, setHasSeenSharePopover] = useLocalStorage<boolean>(
      `hasSeenSharePopover-${albumId}`,
      false,
    );

    const { t } = useTranslation();

    const { copied, copyToClipboard } = useCopyToClipboard(albumIdWithHyphens(albumId));

    useEffect(() => {
      if (!isNameChangeSuccess) return undefined;

      const timeout = setTimeout(() => {
        setIsEditingName(false);
      }, 1000);
      return () => clearTimeout(timeout);
    }, [isNameChangeSuccess]);

    const expiration = expirationDuration(album);

    const durationString = expiration
      ? expiration.days >= 1
        ? `${expiration.days} ${t("day", { count: expiration.days }).toLowerCase()}`
        : expiration.hours >= 1
        ? `${expiration.hours} ${t("hour", { count: expiration.hours }).toLowerCase()}`
        : `${expiration.minutes} ${t("minute", { count: expiration.minutes }).toLowerCase()}`
      : undefined;

    const expirationIsSoon = expiration ? expiration.days < SOON_TO_EXPIRE_THRESHOLD_DAYS : false;
    const expirationHasPassed = expiration ? expiration.hasExpired : false;
    const expiryDateTime = album?.expiryDate ? DateHelper.toStringMMDDWeekday(album.expiryDate) : undefined;

    return (
      <motion.div
        className={styles.albumInformationWrapper}
        variants={slideLeftWhenHiddenVariants(0.5)}
        exit="hidden"
        initial="hidden"
        animate="visible"
        ref={ref}
      >
        <AnimatePresence>
          <div className={styles.topBar}>
            <BackButton onClick={onBack} />
            <PrimaryButton
              ref={shareButtonRef}
              label={t("share")}
              contentfulLabelId="share"
              className={styles.shareButton}
              onClick={onShare}
              isDisabled={expirationHasPassed || isErrorFetchingAlbum}
            />

            <Popover
              withArrow
              anchorRefOverride={shareButtonRef}
              isOpenOverride={!hasSeenSharePopover && !isAlbumInfoModalJustCreatedOpen}
              setIsOpenOverride={() => {
                setHasSeenSharePopover(true);
              }}
              contentClassName={multipleClassNames(styles.popover, styles.resetWidth)}
              data-testid="digital-ride-media-album-header-share-popover"
            >
              <strong data-contentful-label-id="rideMediaAlbumSharePopoverHeading">
                {t("rideMediaAlbumSharePopoverHeading")}
              </strong>
              <p data-contentful-label-id="rideMediaAlbumSharePopoverParagraph">
                {t("rideMediaAlbumSharePopoverParagraph")}
              </p>
            </Popover>
            <DropdownMenu
              contentClassName={styles.dropdownMenu}
              triggerTestId={ALBUM_HEADER_MENU_BUTTON_TEST_ID}
              triggerButton={{
                buttonType: "GhostButton",
                iconCenterNew: "more-vertical",
                className: styles.menuButton,
              }}
              itemGroups={[
                {
                  items: [
                    {
                      label: t("rideMediaAlbumMenuOptionChangeName"),
                      rightSlot: { name: "edit", size: "xl" },
                      onClick: () => {
                        setAlbumName(album?.name ?? "");
                        resetNameChange();
                        setIsEditingName(true);
                      },
                      disabled: isErrorFetchingAlbum,
                    },
                  ],
                },
                {
                  items: [
                    {
                      label: t("rideMediaGeneralAlbumCode"),
                      rightSlot: { name: "qr-code", size: "xl" },
                      onClick: onShowAlbumIdQrCode,
                    },
                  ],
                },
                {
                  items: [
                    {
                      label: t("rideMediaAlbumMenuOptionSendCode"),
                      rightSlot: { name: "send-to-mobile", size: "xl" },
                      onClick: onSendCodeToMe,
                    },
                  ],
                },
                {
                  items: [
                    {
                      label: t("rideMediaAlbumMenuOptionAlbumInfo"),
                      rightSlot: { name: "info", size: "xl" },
                      onClick: onShowAlbumInfo,
                    },
                  ],
                },
                {
                  items: [
                    {
                      label: t("rideMediaAlbumMenuOptionHelp"),
                      rightSlot: { name: "support-agent", size: "xl" },
                      onClick: onHelp,
                    },
                  ],
                },
                {
                  items: [
                    {
                      label: t("rideMediaAlbumMenuOptionLeaveAlbum"),
                      rightSlot: { name: "exit", size: "xl" },
                      onClick: onLeaveAlbum,
                    },
                  ],
                },
                {
                  items: [
                    {
                      label: t("rideMediaAlbumMenuOptionRemoveAlbum"),
                      rightSlot: { name: "trash", size: "xl" },
                      onClick: onDeleteAlbum,
                      testId: "digital-ride-media-album-header-menu-delete-album",
                    },
                  ],
                },
              ]}
            />
          </div>
          {album && !isEditingName && (
            <motion.h2
              initial={{ opacity: 0 }}
              animate={{ opacity: 1 }}
              transition={{ delay: 0.3 }}
              key="album-name"
              ref={titleRef}
            >
              {album.name}
            </motion.h2>
          )}

          {album && isEditingName && (
            <motion.div
              key="album-name-input"
              initial={{ opacity: 0 }}
              animate={{ opacity: 1 }}
              className={styles.inputWrapper}
              data-has-error={gotErrorUpdatingName}
            >
              <InputField
                value={albumName}
                onChange={(_, value) => {
                  setAlbumName(value);
                }}
                inputClassName="h2"
                isValid={!gotErrorUpdatingName}
              />
              <PrimaryButton
                iconCenterNew={
                  isPendingNameChange
                    ? "loading"
                    : isNameChangeSuccess
                    ? "done"
                    : gotErrorUpdatingName
                    ? undefined
                    : "save"
                }
                label={gotErrorUpdatingName ? t("okay") : undefined}
                contentfulLabelId={gotErrorUpdatingName ? "okay" : undefined}
                onClick={() => {
                  if (isNameChangeSuccess) {
                    return;
                  }
                  if (!gotErrorUpdatingName) {
                    updateName(albumName);
                  } else {
                    resetNameChange();
                    setIsEditingName(false);
                  }
                }}
                isDisabled={isPendingNameChange}
              />
              <InputError
                showError={gotErrorUpdatingName}
                errorText={`${t("somethingWentWrong")}. ${t("tryAgain")}`}
                isRequired={false}
              />
            </motion.div>
          )}
          {isLoadingAlbum && (
            <SkeletonRectangle key="album-name-skeleton" animate={{ opacity: 1 }} exit={{ opacity: 0 }} />
          )}
        </AnimatePresence>
        <div className={styles.pills}>
          {durationString && !isLoadingAlbum && (
            <Popover
              contentClassName={styles.popover}
              triggerButton={
                expirationHasPassed && expiryDateTime ? (
                  <button
                    data-testid="digital-ride-media-album-header-expiration-button-expired"
                    data-contentful-label-id="rideMediaAlbumPageHasExpiredDatePrefix"
                  >
                    {t("rideMediaAlbumPageHasExpiredDatePrefix")} <strong>{expiryDateTime}</strong>
                  </button>
                ) : (
                  <button
                    data-testid="digital-ride-media-album-header-expiration-button-duration"
                    data-contentful-label-id="rideMediaAlbumPageExpirationDatePrefix"
                  >
                    {t("rideMediaAlbumPageExpirationDatePrefix")} <strong>{durationString}</strong>
                    {expirationIsSoon && <Icon name="warning" />}
                  </button>
                )
              }
            >
              <p data-contentful-label-id="rideMediaAlbumPageExpirationPopoverText">
                {t("rideMediaAlbumPageExpirationPopoverText")}
              </p>
            </Popover>
          )}
          {isLoadingAlbum && <SkeletonRectangle />}
          {!expirationHasPassed && (
            <Popover
              contentClassName={styles.popover}
              triggerButton={
                <button
                  onClick={copyToClipboard}
                  data-testid="digital-ride-media-album-header-album-id-button"
                  data-contentful-label-id="rideMediaGeneralAlbumCode"
                >
                  {t("rideMediaGeneralAlbumCode")}: <strong>{albumIdWithHyphens(albumId)}</strong>{" "}
                  <Icon name={copied ? "done" : "copy"} />
                </button>
              }
            >
              <p
                data-testid="digital-ride-media-album-header-album-id-popover"
                data-contentful-label-id="rideMediaAlbumPageSendCodePopoverText"
              >
                {t("rideMediaAlbumPageSendCodePopoverText")}
              </p>
            </Popover>
          )}
        </div>
        {album && !album.locked && !expirationHasPassed && (
          <div className={multipleClassNames(styles.pills, styles.albumUnlockedPill)}>
            <Popover
              contentClassName={multipleClassNames(styles.popover, styles.albumUnlockedPopover)}
              triggerButton={
                <button className={styles.pill} data-testid="digital-ride-media-album-block-album-unlocked-button">
                  <strong>{t("rideMediaAlbumPageAlbumUnlockedButtonText")} </strong>
                </button>
              }
            >
              <p data-testid="digital-ride-media-album-block-album-unlocked-popover">
                {t("rideMediaAlbumPageAlbumUnlockedPopoverText")}
              </p>
            </Popover>
          </div>
        )}
      </motion.div>
    );
  },
);

AlbumHeader.displayName = "AlbumHeader";
