import structure from "@/core/styling/structure.module.less";
import styles from "./digital-ride-media-album-block.module.less";
import { BrowserSupportHelper, DateHelper, NotificationHelper, TodayHelper, multipleClassNames } from "@/core/helpers";
import { IDigitalRideMediaService } from "@/core/services/digital-ride-media-service";
import { Fragment, useEffect, useMemo, useState } from "react";
import { SkeletonRectangle } from "@/core/components/primitives/skeleton-rectangle/skeleton-rectangle";
import { useHashState, useLocalStorage } from "@/core/hooks";
import { AnimatePresence, LayoutGroup, motion } from "framer-motion";
import { useMutation, useQuery, useQueryClient } from "@tanstack/react-query";
import {
  AddNewMediaGridItem,
  AlbumHeader,
  AlbumIdQrCodeModal,
  ConfirmationModal,
  PurchaseMedia,
  SendAlbumIdModal,
  AlbumInfoModal,
  VideoPlaceholderModal,
} from "./elements";
import { useTranslation } from "react-i18next";
import SegmentedControls from "@/core/components/primitives/segmented-controls/segmented-controls";
import { GridMediaItem } from "./elements";
import { FocusedMediaModal } from "./elements";
import {
  SUCCESS_NOTIFICATION,
  WARNING_NOTIFICATION,
} from "@/core/components/primitives/notification-center/constants/notification-types";
import {
  PurchasedState,
  createFileFromMedia,
  downloadAllMedia,
  expirationDuration,
  getMediasWithUpcomingVideoById,
} from "../helpers";
import Banner from "@/core/components/primitives/banner/banner";
import { fadeUpWhenHiddenVariants, slideLeftWhenHiddenVariants, slideRightWhenHiddenVariants } from "./elements";
import { Media } from "@parksandresorts/webapiproxy-types";
import { LinkReference } from "@/core/components/primitives/rich-text/rich-text";
import { z } from "zod";
import { sortBy } from "lodash-es";
import { ListIteratee, Many } from "lodash";
import BottomActionButtons from "@/core/components/primitives/bottom-action-buttons/bottom-action-buttons";
import { useProduct, useProducts } from "@/core/hooks/product-hooks";
import { useConfetti } from "@/core/components/primitives/confetti-launcher/confetti-launcher";

const albumBlockHashSchema = z.object({
  showAlbumInfoModalInfo: z.boolean().optional(),
  showAlbumInfoModalJustCreated: z.boolean().optional(),
  highlightMediaId: z.string().optional(),
});

type Props = {
  albumId: string;
  shareUrl: string;
  service: IDigitalRideMediaService;
  purchaseProductGlkIds: {
    photo: number;
    video: number;
    album: number;
    albumUpgradeByMediaBought: Record<number, number>;
  };
  rideMediaSearchAttractions: Array<{ rideId: number; hasVideo: boolean }>;
  physicalProductsLink: LinkReference;
  confirmationPageSlug: string;
  navigateToSearch: () => void;
  navigateToStart: () => void;
  navigateToHelp: () => void;
};

const PURCHASE_PLACEHOLDER_MINUTES_LIMIT = 5;

/**
 * Sort first by createTime and then videos before photos
 * Videos associated to an photo will have the same createTime as the photo
 */
const MEDIA_SORTER: Many<ListIteratee<Media>> = [
  (m) => new Date(m.createTime),
  (m) => (m.mediaType === "Video" ? 0 : 1),
];

const DigitalRideMediaAlbumBlock = ({
  albumId,
  shareUrl,
  service,
  purchaseProductGlkIds,
  rideMediaSearchAttractions,
  physicalProductsLink,
  confirmationPageSlug,
  navigateToSearch,
  navigateToStart,
  navigateToHelp,
}: Props) => {
  const queryClient = useQueryClient();

  const photoProduct = useProduct(purchaseProductGlkIds.photo);
  const videoProduct = useProduct(purchaseProductGlkIds.video);
  const albumProduct = useProduct(purchaseProductGlkIds.album);

  const { confettiLauncher } = useConfetti();

  const [savedAlbumsIds, setSavedAlbumsIds] = useLocalStorage<Array<string>>("savedRideMediaAlbumIds", []);
  const [purchasedRideMedia] = useLocalStorage<PurchasedState>("purchasedRideMedia", {});
  const [hashData, setHashData] = useHashState(albumBlockHashSchema);

  const [focusedMediaId, setFocusedMediaId] = useState<string>();
  const [focusedVideoPlaceholderMediaId, setFocusedVideoPlaceholderMediaId] = useState<string>();

  const [showSendAlbumIdModal, setShowSendAlbumIdModal] = useState(false);
  const [showAlbumIdQrCodeModal, setShowAlbumIdQrCodeModal] = useState(false);
  const [showDeleteAlbumConfirmationModal, setShowDeleteAlbumConfirmationModal] = useState(false);
  const [showLeaveAlbumConfirmationModal, setShowLeaveAlbumConfirmationModal] = useState(false);
  const [showingLockedOrUnlockedMedia, setShowingLockedOrUnlockedMedia] = useState<"locked" | "unlocked">("locked");
  const [isSelectingMediaForPurchase, setIsSelectingMediaForPurchase] = useState(false);
  const [selectedMediaIdsForPurchase, setSelectedMediaIdsForPurchase] = useState<Array<string>>([]);
  const [isPurchasing, setIsPurchasing] = useState(false);
  const [purchaseType, setPurchaseType] = useState<"album" | "individual">("album");

  const recentlyPurchasedMediaIdsForAlbum =
    purchasedRideMedia[albumId]
      ?.filter((purchaseData) => {
        const minutesSincePurchase = DateHelper.durationBetween(
          TodayHelper.getNow(),
          purchaseData.purchasedOn,
          "minutes",
        );
        return minutesSincePurchase < PURCHASE_PLACEHOLDER_MINUTES_LIMIT;
      })
      .flatMap((purchaseData) => purchaseData.mediaIds) ?? [];

  const {
    isPending: isLoadingAlbum,
    data: album,
    error: albumFetchError,
    // eslint-disable-next-line @tanstack/query/exhaustive-deps
  } = useQuery({
    queryKey: ["album", albumId],
    queryFn: () => service.fetchAlbum(albumId),
    select: (data) => data.item,
    staleTime: 1000 * 60 * 5, // Data is considered stale after 5 minutes.
  });
  const isAlbumLocked = album?.locked;
  const albumVisitDate = album?.visitDate;
  const hasVisitDateMismatch = !!albumVisitDate && !DateHelper.isEqualYYYYMMDD(albumVisitDate, TodayHelper.getNow());

  const {
    isPending: isLoadingMedia,
    data: albumMedia,
    error: albumMediaFetchError,
    refetch: refetchAlbumMedia,
    // eslint-disable-next-line @tanstack/query/exhaustive-deps
  } = useQuery({
    queryKey: ["album-media", albumId],
    queryFn: () => service.fetchAlbumMedia(albumId),
    select: (data) => data.media,
    staleTime: 1000 * 60 * 5,
  });

  const lockedMedia = sortBy(albumMedia?.items?.filter((media) => media.locked) ?? [], MEDIA_SORTER);
  const unlockedMedia = sortBy(albumMedia?.items?.filter((media) => !media.locked) ?? [], MEDIA_SORTER);

  const albumPrice = albumProduct?.glkProduct.priceIncludingVat ?? 0;
  const photoPrice = photoProduct?.glkProduct.priceIncludingVat ?? 0;
  const videoPrice = videoProduct?.glkProduct.priceIncludingVat ?? 0;
  const isAllMediaSamePrice = photoPrice === videoPrice;

  // The combined price of the currently selected media, if bought individually.
  const selectedMediaPriceSum = useMemo(() => {
    return selectedMediaIdsForPurchase.reduce((sum, mediaId) => {
      const media = albumMedia?.items?.find((item) => item.mediaId === mediaId);
      if (!media) return sum;
      return sum + (media.mediaType === "Photo" ? photoPrice : videoPrice);
    }, 0);
  }, [selectedMediaIdsForPurchase, albumMedia, photoPrice, videoPrice]);

  /**
   * Media previously purchased: bought individually on any past purchase on this device (purchasedRideMedia localStorage),
   * or already unlocked on the server (e.g. bought on another device/browser). Used for album upgrade discount.
   */
  const previouslyPurchasedMediaIds = useMemo(() => {
    const purchasedIds = (purchasedRideMedia[albumId] ?? []).flatMap((purchaseData) => purchaseData.mediaIds);
    const unlockedIds = unlockedMedia.map((media) => media.mediaId);
    return Array.from(new Set([...purchasedIds, ...unlockedIds]));
  }, [purchasedRideMedia, albumId, unlockedMedia]);

  /** Note: based on current prices, so might be misleading if the price has changed. */
  const previouslyPurchasedPriceSum = useMemo(() => {
    return previouslyPurchasedMediaIds.reduce((sum, mediaId) => {
      const media = albumMedia?.items?.find((item) => item.mediaId === mediaId);
      if (!media) return sum;
      return sum + (media.mediaType === "Photo" ? photoPrice : videoPrice);
    }, 0);
  }, [previouslyPurchasedMediaIds, albumMedia, photoPrice, videoPrice]);

  const totalPurchasedAndSelectedPriceSum = previouslyPurchasedPriceSum + selectedMediaPriceSum;

  const automaticallyConvertedToAlbum = albumPrice > 0 && totalPurchasedAndSelectedPriceSum >= albumPrice;

  /** Auto-upgrade triggered by media bought on a previous visit → charge only the difference. */
  const isDiscountedUpgrade = automaticallyConvertedToAlbum && previouslyPurchasedPriceSum > 0;

  const albumUpgradeGlkIds = purchaseProductGlkIds.albumUpgradeByMediaBought;
  const { productsById: albumUpgradeProductsById } = useProducts(Object.values(albumUpgradeGlkIds));

  const albumUpgradePriceByMediaBought = useMemo(
    () =>
      Object.fromEntries(
        Object.entries(albumUpgradeGlkIds).map(([mediaBought, glkId]) => [
          Number(mediaBought),
          albumUpgradeProductsById.get(glkId)?.glkProduct.priceIncludingVat ?? 0,
        ]),
      ),
    [albumUpgradeGlkIds, albumUpgradeProductsById],
  );

  /** Price to upgrade for this customer, falling back to the full album price if no upsell exists for that count. */
  const albumUpgradePrice = albumUpgradePriceByMediaBought[previouslyPurchasedMediaIds.length] ?? albumPrice;

  // Briefly celebrate (confetti + a small pop on the helper text) the first time the selection reaches
  // the album price in a given selection session. We only do it once per session so repeatedly crossing
  // the threshold (by selecting/deselecting media) doesn't nag the user with the animation over and over.
  const [celebrateConversion, setCelebrateConversion] = useState(false);

  useEffect(() => {
    // Start each new selection session with a fresh celebration.
    if (!isSelectingMediaForPurchase) {
      setCelebrateConversion(false);
    }
  }, [isSelectingMediaForPurchase]);

  useEffect(() => {
    if (!isSelectingMediaForPurchase || !automaticallyConvertedToAlbum || celebrateConversion) return;

    confettiLauncher(["bottom"]);
    setCelebrateConversion(true);
  }, [isSelectingMediaForPurchase, automaticallyConvertedToAlbum, confettiLauncher, celebrateConversion]);

  const numberOfPurchasedMediaNotYetUnlocked = lockedMedia.filter((media) =>
    recentlyPurchasedMediaIdsForAlbum.includes(media.mediaId),
  ).length;

  useEffect(() => {
    if (albumMedia?.items?.some((media) => !media.locked) || numberOfPurchasedMediaNotYetUnlocked > 0) {
      setShowingLockedOrUnlockedMedia("unlocked");
    }
  }, [albumMedia, numberOfPurchasedMediaNotYetUnlocked]);

  useEffect(() => {
    if (!album) return undefined;

    //When album has loaded, set timeout to stop highlighting media
    const timeout = setTimeout(() => {
      setHashData({
        highlightMediaId: undefined,
      });
    }, 5_000);

    return () => {
      clearTimeout(timeout);
    };
  }, [album, setHashData]);

  const {
    mutate: updateName,
    error: updateNameError,
    isPending: isPendingNameChange,
    isSuccess: isNameChangeSuccess,
    reset: resetNameChange,
  } = useMutation({
    mutationFn: (newName: string) => service.updateName(albumId, newName),
    onSuccess: (data) => {
      NotificationHelper.addNotification({
        headline: t("rideMediaAlbumNameChangeNotification"),
        notificationType: SUCCESS_NOTIFICATION,
        displayTime: 3,
      });
      queryClient.setQueryData(["album", albumId], { item: data.item });
    },
  });

  const {
    mutate: addContactInformation,
    error: addContactInformationError,
    isPending: isPendingContactInformationChange,
    isSuccess: isContactInformationChangeSuccess,
    reset: resetContactInformationChange,
  } = useMutation({
    mutationFn: (data: { type: "email" | "phone"; contactInformation: string }) =>
      service.addContactInformationToAlbum(albumId, data.type, data.contactInformation),
    onSuccess: (data) => {
      NotificationHelper.addNotification({
        headline: t("rideMediaAlbumPageSendCodeConfirmation"),
        notificationType: SUCCESS_NOTIFICATION,
        displayTime: 3,
      });
      queryClient.setQueryData(["album", albumId], { item: data.item });
    },
  });

  const [isRemovingMediaIds, setIsRemovingMediaIds] = useState<Array<string>>([]);
  const { mutate: removeMediaFromAlbum } = useMutation({
    mutationFn: (mediaIds: Array<string>) => service.deleteMediaFromAlbum(albumId, mediaIds),
    onMutate: (mediaIds) => {
      setIsRemovingMediaIds(mediaIds);
    },
    onSuccess: (data) => {
      setIsRemovingMediaIds([]);
      NotificationHelper.addNotification({
        headline: t("rideMediaAlbumRemoveMediaConfirmation"),
        notificationType: SUCCESS_NOTIFICATION,
        displayTime: 3,
      });
      queryClient.setQueryData(["album-media", albumId], data);
    },
    onError: (error) => {
      setIsRemovingMediaIds([]);
      console.error("Error removing media", error);
      NotificationHelper.addNotification({
        headline: t("somethingWentWrong"),
        notificationType: WARNING_NOTIFICATION,
        displayTime: 3,
      });
    },
  });

  const {
    mutate: removeAlbum,
    isPending: isPendingRemoveAlbum,
    isSuccess: isRemoveAlbumSuccess,
  } = useMutation({
    mutationFn: () => service.deleteAlbum(albumId),
    onSuccess: async () => {
      NotificationHelper.addNotification({
        headline: t("rideMediaAlbumRemoveAlbumConfirmation"),
        notificationType: SUCCESS_NOTIFICATION,
        displayTime: 3,
      });
      forgetAlbumAndNavigateHome();
    },
    onError: (error) => {
      console.error("Error removing album", error);
      setShowDeleteAlbumConfirmationModal(false);
      NotificationHelper.addNotification({
        headline: t("somethingWentWrong"),
        notificationType: WARNING_NOTIFICATION,
        displayTime: 3,
      });
    },
  });

  const { mutate: startDownloadingAllMedia, isPending: isDownloadingAllMedia } = useMutation({
    mutationFn: (data: { media: Array<Media> }) => downloadAllMedia(data.media),
    onError(error) {
      console.error("Error downloading all media", error);
      NotificationHelper.addNotification({
        headline: t("somethingWentWrong"),
        notificationType: WARNING_NOTIFICATION,
        displayTime: 3,
      });
    },
  });

  const { mutate: socialShareAllMedia, isPending: isSharingAllMedia } = useMutation({
    mutationFn: async (data: { media: Array<Media> }) => {
      const allFiles = await Promise.all(data.media.map(async (media) => await createFileFromMedia(media)));
      const filteredFiles = allFiles.filter((file) => file !== undefined) as File[];
      const shareData = {
        title: t("rideMediaAlbumShareAllMediaTitle"),
        files: filteredFiles,
      } satisfies ShareData;
      return navigator.share(shareData).catch((error) => {
        //For some reason, if the user cancels the share, it throws an error.
        //We don't want to show an error message in that case.
        if (error.name !== "AbortError") {
          throw error;
        }
      });
    },
    onError(error) {
      console.error("Error sharing all media", error);
      NotificationHelper.addNotification({
        headline: t("somethingWentWrong"),
        notificationType: WARNING_NOTIFICATION,
        displayTime: 3,
      });
    },
  });

  useEffect(() => {
    const albumIsNotSaved = !savedAlbumsIds.includes(albumId);
    const albumExists = album !== undefined;
    const isAboutToOrHasBeenRemoved = isRemoveAlbumSuccess || isPendingRemoveAlbum;
    const isCurrentlyLeavingAlbum = isAboutToOrHasBeenRemoved || showLeaveAlbumConfirmationModal;
    if (albumIsNotSaved && albumExists && !isCurrentlyLeavingAlbum) {
      setSavedAlbumsIds([...savedAlbumsIds, albumId]);
    }
  }, [
    albumId,
    savedAlbumsIds,
    setSavedAlbumsIds,
    album,
    isPendingRemoveAlbum,
    isRemoveAlbumSuccess,
    showLeaveAlbumConfirmationModal,
  ]);

  const { t } = useTranslation();

  const forgetAlbumAndNavigateHome = () => {
    setSavedAlbumsIds(savedAlbumsIds.filter((id) => id !== albumId));
    navigateToStart();
  };

  const isErrorFetchingAlbum = !!albumFetchError || !!albumMediaFetchError;

  const showLockedMedia = showingLockedOrUnlockedMedia === "locked" && albumMedia;
  const showUnlockedMedia =
    showingLockedOrUnlockedMedia === "unlocked" &&
    (unlockedMedia.length > 0 || numberOfPurchasedMediaNotYetUnlocked > 0);
  const hasAnyLockedMedia = lockedMedia.length > 0;

  const mediasWithUpcomingVideoById = getMediasWithUpcomingVideoById(
    albumMedia?.items ?? [],
    rideMediaSearchAttractions,
  );

  const hasPurchasedMediaNotYetUnlocked = numberOfPurchasedMediaNotYetUnlocked > 0;
  const hasMediaWithUpcomingVideo = Object.keys(mediasWithUpcomingVideoById).length > 0;
  useEffect(() => {
    if (!hasPurchasedMediaNotYetUnlocked && !hasMediaWithUpcomingVideo) {
      return undefined;
    }

    // We should retry every 10 seconds, but give up after 5 minutes.
    const retryInterval = 10_000;
    const retryDuration = 5 * 60_000;

    const intervalId = setInterval(() => {
      refetchAlbumMedia();
    }, retryInterval);
    const timeout = setTimeout(() => {
      clearInterval(intervalId);
    }, retryDuration);

    return () => {
      clearInterval(intervalId);
      clearTimeout(timeout);
    };
  }, [hasPurchasedMediaNotYetUnlocked, hasMediaWithUpcomingVideo, refetchAlbumMedia]);

  const shareAlbum = async () => {
    const shareData = {
      title: t("rideMediaAlbumPageShareAlbumTitle"),
      url: shareUrl,
    } satisfies ShareData;
    try {
      await navigator.share(shareData);
    } catch (err) {
      console.error("Error sharing:", err);
    }
  };

  const focusedMedia = albumMedia?.items?.find((media) => media.mediaId === focusedMediaId);
  const focusedVideoPlaceholderMedia = albumMedia?.items?.find(
    (media) => media.mediaId === focusedVideoPlaceholderMediaId,
  );
  const expiration = expirationDuration(album);
  const showExpirationBanner = expiration && expiration.hasExpired;

  return (
    <section className={multipleClassNames(styles.outerWrapper, structure.block, structure.blockMaxWidthM)}>
      <LayoutGroup>
        <motion.div className={styles.wrapper} layout="position">
          <AnimatePresence mode="popLayout">
            {!isPurchasing && (
              <AlbumHeader
                key="albumHeader"
                albumId={albumId}
                album={album}
                isLoadingAlbum={isLoadingAlbum}
                isAlbumInfoModalJustCreatedOpen={hashData.showAlbumInfoModalJustCreated ?? false}
                isErrorFetchingAlbum={isErrorFetchingAlbum}
                updateName={updateName}
                resetNameChange={resetNameChange}
                isPendingNameChange={isPendingNameChange}
                isNameChangeSuccess={isNameChangeSuccess}
                gotErrorUpdatingName={!!updateNameError}
                onShare={shareAlbum}
                onBack={navigateToStart}
                onDeleteAlbum={() => {
                  setShowDeleteAlbumConfirmationModal(true);
                }}
                onLeaveAlbum={() => {
                  setShowLeaveAlbumConfirmationModal(true);
                }}
                onHelp={navigateToHelp}
                onShowAlbumIdQrCode={() => setShowAlbumIdQrCodeModal(true)}
                onSendCodeToMe={() => {
                  setShowSendAlbumIdModal(true);
                }}
                onShowAlbumInfo={() => setHashData({ showAlbumInfoModalInfo: true })}
              />
            )}
            {isErrorFetchingAlbum && (
              <motion.div
                className={styles.bannerWrapper}
                key="errorBanner"
                initial="hidden"
                animate="visible"
                exit="hidden"
                variants={slideRightWhenHiddenVariants(0.5)}
              >
                <Banner
                  type="critical"
                  heading={t("somethingWentWrong")}
                  paragraph={t("rideMediaAlbumPageErrorFetching")}
                  data-testid="digital-ride-media-album-error-fetching-banner"
                />
              </motion.div>
            )}
            {!showExpirationBanner && !isPurchasing && !isErrorFetchingAlbum && (
              <motion.div
                key="mediaWrapper"
                className={styles.mediaWrapper}
                animate="visible"
                exit="hidden"
                variants={slideLeftWhenHiddenVariants(0.5)}
              >
                {isAlbumLocked && (unlockedMedia.length > 0 || numberOfPurchasedMediaNotYetUnlocked > 0) && (
                  <SegmentedControls
                    name="lockedOrUnlockedMedia"
                    dateKey="N/A"
                    segments={[
                      {
                        label: t("rideMediaAlbumPagePurchasedMediaHeading"),
                        value: "unlocked",
                      },
                      {
                        label: t("rideMediaAlbumPageNonPurchasedMediaHeading"),
                        value: "locked",
                      },
                    ]}
                    selectedValue={showingLockedOrUnlockedMedia}
                    onChange={(value) => {
                      setShowingLockedOrUnlockedMedia(value as "locked" | "unlocked");
                    }}
                    data-testid={`digital-ride-media-album-segmented-controls-showing-${showingLockedOrUnlockedMedia}-media`}
                  />
                )}
                <AnimatePresence mode="popLayout">
                  {showLockedMedia && (
                    <motion.div
                      className={styles.mediaGrid}
                      key="lockedGrid"
                      initial="hidden"
                      animate="visible"
                      exit="hidden"
                      variants={slideLeftWhenHiddenVariants(1)}
                      data-testid="digital-ride-media-album-locked-media-grid"
                    >
                      {!hasVisitDateMismatch && (
                        <AddNewMediaGridItem disabled={isSelectingMediaForPurchase} onClick={navigateToSearch} />
                      )}
                      {lockedMedia.map((media) => (
                        <Fragment key={`${media.mediaId}-${media.mediaType.toLowerCase()}`}>
                          {mediasWithUpcomingVideoById[media.mediaId] && (
                            <GridMediaItem
                              key={`upcoming-${mediasWithUpcomingVideoById[media.mediaId].mediaId}`}
                              media={mediasWithUpcomingVideoById[media.mediaId]}
                              type="placeholderVideo"
                              isHighlighted={false}
                              mode="normal"
                              onClick={() => {
                                setFocusedVideoPlaceholderMediaId(mediasWithUpcomingVideoById[media.mediaId]?.mediaId);
                              }}
                            />
                          )}
                          <GridMediaItem
                            key={`${media.mediaId}-${media.mediaType.toLowerCase()}`}
                            media={media}
                            mode={isSelectingMediaForPurchase ? "selecting" : "normal"}
                            hasBeenSelected={selectedMediaIdsForPurchase.includes(media.mediaId)}
                            isHighlighted={hashData.highlightMediaId === media.mediaId}
                            isBeingRemoved={isRemovingMediaIds.includes(media.mediaId)}
                            onClick={() => {
                              if (isSelectingMediaForPurchase) {
                                setSelectedMediaIdsForPurchase((selectedMediaIds) => {
                                  if (selectedMediaIds.includes(media.mediaId)) {
                                    return selectedMediaIds.filter((id) => id !== media.mediaId);
                                  }
                                  return [...selectedMediaIds, media.mediaId];
                                });
                              } else {
                                setFocusedMediaId(media.mediaId);
                              }
                            }}
                          />
                        </Fragment>
                      ))}
                    </motion.div>
                  )}
                  {showUnlockedMedia && (
                    <motion.div
                      key="unclockedGrid"
                      className={styles.mediaGrid}
                      initial="hidden"
                      animate="visible"
                      exit="hidden"
                      variants={slideRightWhenHiddenVariants(1)}
                      data-testid="digital-ride-media-album-unlocked-media-grid"
                    >
                      {Array.from({ length: Math.min(numberOfPurchasedMediaNotYetUnlocked, 5) }).map((_, index) => (
                        <SkeletonRectangle key={index} />
                      ))}
                      {unlockedMedia.map((media) => (
                        <GridMediaItem
                          key={`${media.mediaId}-${media.mediaType.toLowerCase()}`}
                          media={media}
                          mode="normal"
                          isHighlighted={hashData.highlightMediaId === media.mediaId}
                          onClick={() => {
                            setFocusedMediaId(media.mediaId);
                          }}
                        />
                      ))}
                      {!hasVisitDateMismatch && <AddNewMediaGridItem onClick={navigateToSearch} />}
                    </motion.div>
                  )}
                  {isLoadingMedia && (
                    <motion.div key="skeletonGrid" className={styles.mediaGrid}>
                      {Array.from({ length: 5 }).map((_, index) => (
                        <SkeletonRectangle key={index} animate={{ opacity: 1 }} exit={{ opacity: 0 }} />
                      ))}
                    </motion.div>
                  )}
                </AnimatePresence>
              </motion.div>
            )}

            {/* Locked media */}
            {showLockedMedia && hasAnyLockedMedia && !isSelectingMediaForPurchase && !isPurchasing && (
              <motion.div
                key="lockedActionWrapperNotPurchasing"
                initial="hidden"
                animate="visible"
                exit="hidden"
                variants={slideLeftWhenHiddenVariants(1)}
                className={styles.actionWrapper}
              >
                <BottomActionButtons
                  firstButton={{
                    buttonType: "PrimaryButton",
                    label: t("rideMediaAlbumStartPurchasingAlbumButtonText", { albumPrice: albumUpgradePrice }),
                    contentfulLabelId: "rideMediaAlbumStartPurchasingAlbumButtonText",
                    isFullWidth: true,
                    onClick: () => {
                      setPurchaseType("album");
                      setIsPurchasing(true);
                      window.scrollTo({
                        top: 0,
                        behavior: "smooth",
                      });
                    },
                  }}
                  secondButton={{
                    buttonType: "OutlineButton",
                    label: isAllMediaSamePrice
                      ? t("rideMediaAlbumStartPurchasingMediaSamePriceButtonText", { singleMediaPrice: photoPrice })
                      : t("rideMediaAlbumStartPurchasingMediaDifferentPriceButtonText", {
                          singleMediaPrice: Math.min(photoPrice, videoPrice),
                        }),
                    contentfulLabelId: isAllMediaSamePrice
                      ? "rideMediaAlbumStartPurchasingMediaSamePriceButtonText"
                      : "rideMediaAlbumStartPurchasingMediaDifferentPriceButtonText",
                    testId: "digital-ride-media-album-start-purchasing-media-button",
                    isFullWidth: true,
                    onClick: () => {
                      setPurchaseType("individual");
                      setIsSelectingMediaForPurchase(true);
                    },
                  }}
                  direction="vertical"
                />
              </motion.div>
            )}

            {/* Select media for purchase */}
            {showLockedMedia && hasAnyLockedMedia && isSelectingMediaForPurchase && !isPurchasing && (
              <motion.div
                key="lockedActionWrapperPurchasing"
                initial="hidden"
                animate="visible"
                exit="hidden"
                variants={slideRightWhenHiddenVariants(1)}
                className={styles.actionWrapper}
              >
                <BottomActionButtons
                  firstButton={{
                    buttonType: "OutlineButton",
                    label: t("cancel"),

                    onClick: () => {
                      setIsSelectingMediaForPurchase(false);
                    },
                    isFullWidth: true,
                  }}
                  secondButton={{
                    buttonType: "PrimaryButton",
                    label: automaticallyConvertedToAlbum
                      ? t("rideMediaAlbumPurchaseAlbumButtonText")
                      : t("rideMediaAlbumPurchaseNMediaButtonText", { count: selectedMediaIdsForPurchase.length }),
                    contentfulLabelId: automaticallyConvertedToAlbum
                      ? "rideMediaAlbumPurchaseAlbumButtonText"
                      : "rideMediaAlbumPurchaseNMediaButtonText",
                    testId: automaticallyConvertedToAlbum
                      ? "digital-ride-media-album-purchase-converted-to-album-button"
                      : "digital-ride-media-album-purchase-selected-media-button",
                    isDisabled: selectedMediaIdsForPurchase.length === 0,
                    isFullWidth: true,
                    onClick: () => {
                      // When the selected media already costs as much as (or more than) the album, upgrade to the full album.
                      setPurchaseType(automaticallyConvertedToAlbum ? "album" : "individual");
                      setIsPurchasing(true);
                      window.scrollTo({
                        top: 0,
                        behavior: "smooth",
                      });
                    },
                  }}
                >
                  <AnimatePresence mode="popLayout" initial={false}>
                    {isDiscountedUpgrade ? (
                      <motion.p
                        key="upgradeDiscountHelper"
                        data-testid="digital-ride-media-album-upgrade-discount-helper"
                        data-contentful-id="rideMediaAlbumPurchaseUpgradeToAlbumDiscountHelperText"
                        variants={fadeUpWhenHiddenVariants()}
                        initial="hidden"
                        animate="celebrate"
                        exit="hidden"
                      >
                        {t("rideMediaAlbumPurchaseUpgradeToAlbumDiscountHelperText", {
                          remainingPrice: albumUpgradePrice,
                        })}
                      </motion.p>
                    ) : automaticallyConvertedToAlbum ? (
                      <motion.p
                        key="reachedAlbumPriceHelper"
                        data-testid="digital-ride-media-album-reached-album-price-helper"
                        data-contentful-id="rideMediaAlbumPurchaseSelectedMediaReachesAlbumPriceHelperText"
                        variants={fadeUpWhenHiddenVariants()}
                        initial="hidden"
                        animate="celebrate"
                        exit="hidden"
                      >
                        {t("rideMediaAlbumPurchaseSelectedMediaReachesAlbumPriceHelperText", {
                          selectedMediaPriceSum,
                          albumPrice,
                        })}
                      </motion.p>
                    ) : (
                      <motion.p
                        key="selectMediaHelper"
                        data-contentful-id="rideMediaAlbumPurchaseNMediaHelperText"
                        variants={fadeUpWhenHiddenVariants()}
                        initial="hidden"
                        animate="celebrate"
                        exit="hidden"
                      >
                        {t("rideMediaAlbumPurchaseNMediaHelperText")}
                      </motion.p>
                    )}
                  </AnimatePresence>
                </BottomActionButtons>
              </motion.div>
            )}

            {/* Unlocked media */}
            {showUnlockedMedia && (
              <motion.div
                key="unlockedActionWrapper"
                initial="hidden"
                animate="visible"
                exit="hidden"
                variants={slideRightWhenHiddenVariants(1)}
                className={styles.actionWrapper}
              >
                <BottomActionButtons
                  firstButton={{
                    buttonType: "PrimaryButton",
                    label: t("rideMediaAlbumSaveAllMediaButtonText"),
                    contentfulLabelId: "rideMediaAlbumSaveAllMediaButtonText",
                    iconRightNew: isDownloadingAllMedia || isSharingAllMedia ? "loading" : undefined,
                    isDisabled: isDownloadingAllMedia || isSharingAllMedia,
                    isFullWidth: true,
                    onClick: () => {
                      if (BrowserSupportHelper.getDeviceType() === "iOS") {
                        //On iOS, the download feature is not great since it prompts to download only _one_ file even if multiple exists.
                        //Therefore, we fallback to sharing but with multiple files for iOS.
                        socialShareAllMedia({ media: unlockedMedia });
                      } else {
                        startDownloadingAllMedia({ media: unlockedMedia });
                      }
                    },
                  }}
                  secondButton={{
                    buttonType: "OutlineButtonLink",
                    label: physicalProductsLink.title,
                    isFullWidth: true,
                    url: physicalProductsLink.internalLink?.slug ?? physicalProductsLink.externalUrl,
                  }}
                  direction="vertical"
                />
              </motion.div>
            )}

            {/* Album has expired */}
            {showExpirationBanner && !isPurchasing && !isErrorFetchingAlbum && (
              <div>
                <div className={styles.bannerWrapper}>
                  <Banner
                    type="inheritTheme"
                    heading={t("rideMediaAlbumPageHasExpiredBannerHeading")}
                    paragraph={t("rideMediaAlbumPageHasExpiredBannerParagraph")}
                    data-testid="digital-ride-media-album-expired-banner"
                    buttonText={t("rideMediaAlbumPageHasExpiredBannerButtonText")}
                    buttonVariant="OutlineButton"
                    onButtonClick={() => {
                      setShowDeleteAlbumConfirmationModal(true);
                    }}
                  />
                </div>
                <div className={styles.actionWrapper}>
                  <BottomActionButtons
                    firstButton={{
                      buttonType: "PrimaryButton",
                      label: t("rideMediaGeneralGoToStart"),
                      contentfulLabelId: "rideMediaGeneralGoToStart",
                      isFullWidth: true,
                      onClick: () => {
                        navigateToStart();
                      },
                    }}
                    secondButton={{
                      buttonType: "OutlineButton",
                      label: t("rideMediaGeneralHelp"),
                      contentfulLabelId: "rideMediaGeneralHelp",
                      isFullWidth: true,
                      onClick: () => {
                        navigateToHelp();
                      },
                    }}
                    direction="vertical"
                  />
                </div>
              </div>
            )}

            {isPurchasing && (
              <PurchaseMedia
                key="purchaseMedia"
                albumId={albumId}
                media={
                  purchaseType === "album"
                    ? lockedMedia
                    : lockedMedia.filter((media) => selectedMediaIdsForPurchase.includes(media.mediaId))
                }
                purchaseType={purchaseType}
                purchaseProductGlkIds={purchaseProductGlkIds}
                previouslyPurchasedMediaCount={previouslyPurchasedMediaIds.length}
                confirmationPageSlug={confirmationPageSlug}
                onBack={() => {
                  setIsPurchasing(false);
                }}
                onSwitchToAlbumPurchase={() => setPurchaseType("album")}
              />
            )}
          </AnimatePresence>
        </motion.div>
        {focusedMedia && (
          <FocusedMediaModal
            isOpen={!!focusedMedia}
            focusedMedia={focusedMedia}
            singleMediaPrice={focusedMedia.mediaType === "Photo" ? photoPrice : videoPrice}
            onClose={() => setFocusedMediaId(undefined)}
            removeMedia={(mediaId) => {
              removeMediaFromAlbum([mediaId]);
            }}
            purchaseSingleMedia={(mediaId) => {
              setPurchaseType("individual");
              setSelectedMediaIdsForPurchase([mediaId]);
              setIsPurchasing(true);
              setFocusedMediaId(undefined);
            }}
          />
        )}

        <AlbumInfoModal
          albumPrice={albumPrice}
          isOpen={!!hashData.showAlbumInfoModalInfo || !!hashData.showAlbumInfoModalJustCreated}
          variant={hashData.showAlbumInfoModalInfo ? "info" : "justCreated"}
          onClose={() =>
            setHashData({
              showAlbumInfoModalJustCreated: false,
              showAlbumInfoModalInfo: false,
            })
          }
        />
        {focusedVideoPlaceholderMedia && (
          <VideoPlaceholderModal
            media={focusedVideoPlaceholderMedia}
            isOpen={!!focusedVideoPlaceholderMedia}
            onClose={() => setFocusedVideoPlaceholderMediaId(undefined)}
          />
        )}

        <SendAlbumIdModal
          isOpen={showSendAlbumIdModal}
          onClose={() => {
            setShowSendAlbumIdModal(false);
            resetContactInformationChange();
          }}
          sendAlbumId={(type, contact) => addContactInformation({ type, contactInformation: contact })}
          isSendingCode={isPendingContactInformationChange}
          isSuccess={isContactInformationChangeSuccess}
          isError={!!addContactInformationError}
        />
        <ConfirmationModal
          isOpen={showDeleteAlbumConfirmationModal}
          isLoading={isPendingRemoveAlbum}
          title={t("rideMediaAlbumDeleteConfirmationHeading")}
          paragraph={
            expiration && expiration.hasExpired
              ? t("rideMediaAlbumDeleteConfirmationParagraphExpiredAlbum")
              : t("rideMediaAlbumDeleteConfirmationParagraph", { count: albumMedia?.items?.length ?? 0 })
          }
          onClose={() => {
            setShowDeleteAlbumConfirmationModal(false);
          }}
          onConfirm={() => {
            removeAlbum();
          }}
        />
        <ConfirmationModal
          isOpen={showLeaveAlbumConfirmationModal}
          isLoading={false}
          title={t("rideMediaAlbumLeaveConfirmationHeading")}
          paragraph={t("rideMediaAlbumLeaveConfirmationParagraph")}
          onClose={() => {
            setShowLeaveAlbumConfirmationModal(false);
          }}
          onConfirm={() => {
            forgetAlbumAndNavigateHome();
          }}
        />
        {album && (
          <AlbumIdQrCodeModal
            isOpen={showAlbumIdQrCodeModal}
            onClose={() => setShowAlbumIdQrCodeModal(false)}
            album={album}
          />
        )}
      </LayoutGroup>
    </section>
  );
};

export default DigitalRideMediaAlbumBlock;
