import { Variants } from "framer-motion";
import styles from "./add-new-media-grid-item.module.less";
import { PrimaryButton } from "@/core/components/primitives/parks-button/parks-button";
import { useTranslation } from "react-i18next";
import Card from "@/core/components/primitives/card/card";

type Props = {
  disabled?: boolean;
  onClick: () => void;
};

const itemVariants = {
  default: {
    opacity: 1,
  },
  disabled: {
    opacity: 0.35,
  },
} satisfies Variants;

export const AddNewMediaGridItem = ({ disabled, onClick }: Props) => {
  const { t } = useTranslation();
  return (
    <Card
      className={styles.item}
      animate={disabled ? "disabled" : "default"}
      variants={itemVariants}
      onClick={onClick}
      whileHover={!disabled ? { scale: 1.05, transition: { delay: 0 } } : undefined}
      whileTap={!disabled ? { scale: 0.95, transition: { delay: 0 } } : undefined}
      data-testid="digital-ride-media-add-new-media-grid-item"
    >
      <PrimaryButton iconLeftNew="add" label={t("rideMediaAlbumAddMoreMedia")} />
    </Card>
  );
};
