import { AnimationProps, motion } from "framer-motion";
import { useState, useEffect, PropsWithChildren } from "react";
import { multipleClassNames } from "@/core/helpers/string-helper";
import styles from "./use-shakeable.module.less";

export type ShakeConfig = {
  /** The amount of degrees to rotate between. It will rotate between negative and positive this value. Defaults to 5 */
  rotationDegrees?: number;
  /** For each repeat of this animation, how many times will it oscillate back and forth between the rotationDegrees. Defaults to 10 */
  shakesPerRepeat?: number;
  /** The duration in milliseconds for each repeat of the animation. Defaults to 5000 */
  durationPerRepeat?: number;
  /** How many times should the animation repeat. Defaults to 1 */
  repeat?: number;
  /** The delay in milliseconds between each repeat. Not used if repeat is 1. Defaults to 1000 */
  repeatDelay?: number;
  /** Any other classes to apply to the wrapper. Especially useful when we want to tell the wrapper to take up 100% of the width */
  wrapperClassName?: string;
};

type Props = {
  /** Any other classes to apply to the wrapper. Especially useful when we want to tell the wrapper to take up 100% of the width */
  wrapperClassName?: string;
};

export const useShakeable = (config?: ShakeConfig) => {
  const {
    rotationDegrees = 5,
    shakesPerRepeat = 10,
    durationPerRepeat = 5000,
    repeat = 1,
    repeatDelay = 1000,
  } = config || {};

  const [isShaking, setIsShaking] = useState(false);

  /**
   * This rotation array holds the values for the rotation animation.
   * If rotationDegrees is 10 and shakesPerRepeat is 5, the array will look like this:
   * [-10, 10, -10, 10, -10, 10, -10, 10, -10, 10, 0].
   * Meaning it will animate back and forth 5 times between -10 and 10 degrees.
   * It will always end with 0 to make sure the element is back to its original position.
   */
  const rotationArray = Array.from({ length: shakesPerRepeat }).flatMap(() => [-1 * rotationDegrees, rotationDegrees]);
  rotationArray.unshift(0);
  rotationArray.push(0);

  const shakeAnimation: AnimationProps["animate"] = isShaking
    ? {
        rotate: rotationArray,
        transition: {
          duration: durationPerRepeat / 1000,
          repeat: repeat,
          repeatDelay: repeatDelay / 1000,
          repeatType: "reverse",
        },
      }
    : { rotate: 0 };

  const timeForShakes = durationPerRepeat * repeat;
  const timeForDelays = (repeat - 1) * repeatDelay;
  const totalAnimationDuration = timeForShakes + timeForDelays;

  const shake = () => {
    setIsShaking(true);
  };

  useEffect(() => {
    if (!isShaking) return undefined;

    const stopShakingTimer = setTimeout(() => {
      setIsShaking(false);
    }, totalAnimationDuration);
    return () => clearTimeout(stopShakingTimer);
  }, [isShaking, totalAnimationDuration]);

  const Shakeable = ({ children, wrapperClassName }: PropsWithChildren<Props>) => (
    <motion.div
      animate={shakeAnimation}
      className={multipleClassNames(styles.wrapper, wrapperClassName ? wrapperClassName : "")}
    >
      {children}
    </motion.div>
  );
  return [Shakeable, shake] as const;
};
