import { Modal } from "@/core/components/primitives/modal/modal";
import { OutlineButton, PrimaryButton } from "@/core/components/primitives/parks-button/parks-button";
import { MODAL_PORTAL_ID } from "@/core/components/primitives/modal-portal/modal-portal";
import { multipleClassNames } from "@/core/helpers";
import { useEffect, useState } from "react";
import { useTranslation } from "react-i18next";
import InputField from "@/core/components/primitives/input-field/input-field";
import StyledRadioButtons from "@/core/components/primitives/styled-radio-buttons/styled-radio-buttons";
import styles from "./send-album-id-modal.module.less";
import Banner from "@/core/components/primitives/banner/banner";
import { AnimatePresence } from "framer-motion";

type Props = {
  isOpen: boolean;
  onClose: () => void;
  sendAlbumId: (type: "email" | "phone", contact: string) => void;
  isSendingCode: boolean;
  isSuccess: boolean;
  isError: boolean;
};

export const SendAlbumIdModal = ({ isOpen, onClose, sendAlbumId, isSendingCode, isSuccess, isError }: Props) => {
  const [sendCodeContactOption, setSendCodeContactOption] = useState<"email" | "phone">("email");
  const [email, setEmail] = useState("");
  const [phone, setPhone] = useState("");

  useEffect(() => {
    if (!isSuccess) return undefined;

    const timeout = setTimeout(() => {
      setEmail("");
      setPhone("");
      onClose();
    }, 1000);
    return () => clearTimeout(timeout);
  }, [isSuccess, onClose]);

  const { t } = useTranslation();
  return (
    <Modal isOpen={isOpen} onClose={onClose} innerClassName={styles.innerModal} portalId={MODAL_PORTAL_ID}>
      <div className={multipleClassNames(styles.modalContent, styles.sendCodeModalContent)}>
        <h3>{t("rideMediaAlbumSendCodeModalHeading")}</h3>
        <p>{t("rideMediaAlbumSendCodeModalParagraph")}</p>
        <StyledRadioButtons
          name="contactOption"
          options={[
            { label: t("email"), value: "email" },
            { label: t("phone"), value: "phone" },
          ]}
          value={sendCodeContactOption}
          onChange={(_, value) => setSendCodeContactOption(value as "email" | "phone")}
        />
        {sendCodeContactOption === "email" && (
          <InputField
            type={"email" as "text"}
            inputMode="email"
            placeholder="example@email.com"
            value={email}
            inputClassName={styles.input}
            onChange={(_, email) => setEmail(email)}
          />
        )}
        {sendCodeContactOption === "phone" && (
          <InputField
            type={"tel" as "text"}
            inputMode="tel"
            placeholder="(+46)71 234 5678"
            value={phone}
            inputClassName={styles.input}
            onChange={(_, phone) => setPhone(phone)}
          />
        )}
        <div className={styles.buttonsContainer}>
          <OutlineButton label={t("noThanks")} isFullWidth onClick={onClose} />
          <PrimaryButton
            label={isSendingCode || isSuccess ? undefined : t("rideMediaAlbumSendCodeModalButtonText")}
            iconCenterNew={isSendingCode ? "loading" : isSuccess ? "check" : undefined}
            isFullWidth
            onClick={() => {
              sendAlbumId(sendCodeContactOption, sendCodeContactOption === "email" ? email : phone);
            }}
          />
        </div>
        <AnimatePresence>
          {isError && (
            <Banner
              animate={{ opacity: 1 }}
              initial={{ opacity: 0 }}
              exit={{ opacity: 0 }}
              type="critical"
              heading={t("somethingWentWrong")}
              paragraph={t("rideMediaAlbumSendCodeModalErrorParagraph")}
            />
          )}
        </AnimatePresence>
      </div>
    </Modal>
  );
};
