import { Modal } from "@/core/components/primitives/modal/modal";
import { MODAL_PORTAL_ID } from "@/core/components/primitives/modal-portal/modal-portal";
import { useTranslation } from "react-i18next";
import styles from "./confirmation-modal.module.less";
import { GhostButton, OutlineButton, PrimaryButton } from "@/core/components/primitives/parks-button/parks-button";

type Props = {
  isOpen: boolean;
  isLoading: boolean;
  title: string;
  paragraph: string;
  onClose: () => void;
  onConfirm: () => void;
};

export const ConfirmationModal = ({ isOpen, isLoading, title, paragraph, onClose, onConfirm }: Props) => {
  const { t } = useTranslation();
  return (
    <Modal isOpen={isOpen} onClose={onClose} innerClassName={styles.innerModal} portalId={MODAL_PORTAL_ID}>
      <div className={styles.modalContent}>
        <GhostButton onClick={onClose} className={styles.closeButton} iconCenterNew="close" />
        <h4>{title}</h4>
        <p>{paragraph}</p>
        <div className={styles.buttonWrapper}>
          <OutlineButton onClick={onClose} isFullWidth label={t("cancel")} />
          <PrimaryButton
            onClick={onConfirm}
            isFullWidth
            iconCenterNew={isLoading ? "loading" : undefined}
            label={isLoading ? undefined : t("rideMediaAlbumDeleteConfirmationModalConfirm")}
            testId="digital-ride-media-confirmation-modal-confirm-button"
          />
        </div>
      </div>
    </Modal>
  );
};
