class BrowserSupportHelper {
  isSupportingInputTypeDate: boolean | undefined;
  isBrowserIE: boolean | undefined;
  constructor() {
    if (typeof window !== "undefined") {
      this.isSupportingInputTypeDate = this.checkInputTypeDateSupport();
      this.isBrowserIE = this.checkIsBrowserIE();
    }
  }

  checkInputTypeDateSupport() {
    if (typeof window === "undefined") {
      return false;
    }

    const input = document.createElement("input");
    input.setAttribute("type", "date");

    const notADateValue = "not-a-date";
    input.setAttribute("value", notADateValue);

    const result = input.value !== notADateValue;
    return result;
  }

  checkIsBrowserIE() {
    if (typeof window === "undefined") {
      return false;
    }

    const ua = window.navigator.userAgent; //Check the userAgent property of the window.navigator object
    const msie = ua.indexOf("MSIE "); // IE 10 or older
    const trident = ua.indexOf("Trident/"); //IE 11

    const isIe = msie > 0 || trident > 0;
    return isIe;
  }

  checkIsBrowserEdge() {
    if (typeof window === "undefined") {
      return false;
    }

    return window.navigator.userAgent.indexOf("Edge") > -1;
  }

  getNavigator() {
    if (typeof window === "undefined") {
      return undefined;
    }
    return window.navigator;
  }

  getDeviceType() {
    const userAgent = this.getNavigator()?.userAgent ?? "";

    // Check for iOS
    if (/iPad|iPhone|iPod/.test(userAgent)) {
      return "iOS";
    }

    // Check for Android
    if (/android/i.test(userAgent)) {
      return "Android";
    }

    // Default to desktop
    return "Desktop";
  }
}

const helper = new BrowserSupportHelper();
export default helper;
export { BrowserSupportHelper };
