import { useLayoutEffect, useRef, useState } from "react";
import { breakpoints } from "@/core/constants/breakpoints";
import { EventAggregator } from "../helpers";
import { debounce } from "lodash-es";

/** Helper function to convert breakpoint values to pixels */
const convertBreakpointToPx = (breakpoint: string): number => {
  const value = breakpoint.match(/(\d*\.?\d+)(rem|px)/);
  if (!value) return 0;
  const [_, num, unit] = value;
  return unit === "rem" ? parseFloat(num) * 16 : parseFloat(num);
};

/** Helper function to compare two arrays */
const arraysAreEqual = (a: Array<string>, b: Array<string>): boolean =>
  a.length === b.length && a.every((value, index) => value === b[index]);

/**
 * Get all the matching breakpoints based on the window's width.
 * It listens for window resize events and updates the breakpoints dynamically.
 *
 * @returns {Array<string>} An array of breakpoint names where the breakpoints are bigger or the same size as the window.
 *
 * @example If window width is 80 rem (1280px) it will return "xsmall, small, medium"
 * (given that '@medium' = 48 rem and '@large' = 90 rem)
 */
export const useMatchingBreakpoints = (): Array<string> => {
  const [matchingBreakpoints, setMatchingBreakpoints] = useState<Array<string>>([]);
  const previousBreakpointsRef = useRef<Array<string>>([]);

  useLayoutEffect(() => {
    const updateMatchingBreakpoints = (innerWidth: number) => {
      const matchingBreakpoints = Object.entries(breakpoints)
        .filter(([, value]) => {
          const pxValue = convertBreakpointToPx(value);
          return pxValue > 0 && innerWidth >= pxValue;
        })
        .sort(([, aWidth], [, bWidth]) => convertBreakpointToPx(aWidth) - convertBreakpointToPx(bWidth))
        .map(([breakpoint]) => breakpoint);

      const newBreakpoints = matchingBreakpoints.length ? matchingBreakpoints : ["unknown"];

      // Compare with the previous breakpoints to avoid unnecessary state updates
      if (!arraysAreEqual(newBreakpoints, previousBreakpointsRef.current)) {
        previousBreakpointsRef.current = newBreakpoints;
        setMatchingBreakpoints(newBreakpoints);
      }
    };

    const debouncedOnResize = debounce(updateMatchingBreakpoints, 100);
    const resizeEventSubscription = EventAggregator.subscribe("onResizeWindowWidth", debouncedOnResize);

    // Get initial matching breakpoints
    updateMatchingBreakpoints(window.innerWidth);

    return () => {
      resizeEventSubscription.remove();
    };
  }, []);

  return matchingBreakpoints;
};
