import {
  Media,
  CartRequestCartItem,
  MediaType,
  DeliveryType,
  CartResponseV2CartItem,
} from "@parksandresorts/webapiproxy-types";
import { ShopServicePayment } from "@/core/components/modules/shop-service-payment/shop-service-payment";
import { useEffect, useMemo } from "react";
import {
  CurrencyHelper,
  LanguageHelper,
  exhaustiveCheck,
  getPrimaryDeliveryType,
  isNonEmptyArray,
  isTruthy,
} from "@/core/helpers";
import { useTranslation } from "react-i18next";
import { GhostButton } from "@/core/components/primitives/parks-button/parks-button";
import styles from "./purchase-media.module.less";
import { motion } from "framer-motion";
import { slideRightWhenHiddenVariants } from "../animations";
import { useAddMultipleItemsToCartMutation, useCart } from "@/core/hooks/shop-service-hooks";
import { CheckoutError, CheckoutLoading } from "@/core/components/primitives/shop-service-status/shop-service-status";
import { cartItemsToAddToCartGTMEvent, trackEcommerceEvent } from "@/core/helpers/gtm-helper";
import { useProduct } from "@/core/hooks/product-hooks";
import Cart from "@/core/components/modules/cart/cart";
import { useStaticConfigContext } from "@/core/contexts";
import { useCartItemsFromCartResponse } from "@/core/hooks";
import Banner from "@/core/components/primitives/banner/banner";
import SummaryList from "@/core/components/primitives/summary-list/summary-list";
import { SummaryTotal } from "@/core/components/primitives/summary-total/summary-total";

type Props = {
  albumId: string;
  media: Array<Media>;
  purchaseProductGlkIds: {
    photo: number;
    video: number;
    album: number;
    /** Album upgrade products mapped by the number of media already bought */
    albumUpgradeByMediaBought: Record<number, number>;
  };
  /**
   * How many media the customer has already bought for this album. Determines which discounted upgrade
   * product (if any) is used when buying the whole album, so they never pay more than the album price.
   */
  previouslyPurchasedMediaCount: number;
  purchaseType: "album" | "individual";
  confirmationPageSlug: string;
  onBack: () => void;
  onSwitchToAlbumPurchase: () => void;
};

export const PurchaseMedia = ({
  albumId,
  media,
  purchaseProductGlkIds,
  previouslyPurchasedMediaCount,
  purchaseType,
  confirmationPageSlug,
  onBack,
  onSwitchToAlbumPurchase,
}: Props) => {
  const { t } = useTranslation();
  const { eCommerce } = useStaticConfigContext();

  const photoProduct = useProduct(purchaseProductGlkIds.photo);
  const videoProduct = useProduct(purchaseProductGlkIds.video);
  const albumProduct = useProduct(purchaseProductGlkIds.album);
  const albumUpgradeProduct = useProduct(
    purchaseProductGlkIds.albumUpgradeByMediaBought[previouslyPurchasedMediaCount],
  );
  // Charge the discounted upgrade price when the customer has already bought media, otherwise the full album.
  const albumProductToCharge = albumUpgradeProduct ?? albumProduct;

  const cartItems = useMemo<Array<CartRequestCartItem & CartResponseV2CartItem>>(() => {
    if (purchaseType === "album") {
      const price = albumProductToCharge?.price;
      if (!albumProductToCharge || !albumProductToCharge.productId || !price) {
        return [];
      }
      return [
        {
          productId: albumProductToCharge.productId,
          quantity: 1,
          deliveryType: getPrimaryDeliveryType(albumProductToCharge, DeliveryType.DIGITAL),
          data: {
            attractionAlbumV1: {
              albumId,
            },
          },
          // the below parts are mocked versions of a CartResponseV2CartItem, used to show data while the cart is being created/loaded
          cartItemGuid: `mocked ${albumId}-album`,
          price: {
            amount: {
              amountIncludingVat: albumProductToCharge.glkProduct.priceIncludingVat,
              vatAmount: 0,
            },
            unitPriceIncludingVat: albumProductToCharge.glkProduct.priceIncludingVat,
            vatPercentage: 0,
          },
          productName: albumProductToCharge.name,
        } satisfies CartRequestCartItem & CartResponseV2CartItem,
      ];
    }

    return media
      .map((mediaItem) => {
        const product =
          mediaItem.mediaType === MediaType.PHOTO
            ? photoProduct
            : mediaItem.mediaType === MediaType.VIDEO
            ? videoProduct
            : exhaustiveCheck(mediaItem.mediaType);

        if (!product) {
          return undefined;
        }

        return {
          productId: product.productId,
          quantity: 1,
          deliveryType: getPrimaryDeliveryType(product, DeliveryType.DIGITAL),
          data: {
            attractionMediaV1: {
              albumId,
              mediaId: mediaItem.mediaId,
            },
          },
          // the below parts are mocked versions of a CartResponseV2CartItem, used to show data while the cart is being created/loaded
          cartItemGuid: `mocked ${albumId}-${mediaItem.mediaId}`,
          price: {
            amount: {
              amountIncludingVat: product.glkProduct.priceIncludingVat,
              vatAmount: 0,
            },
            unitPriceIncludingVat: product.glkProduct.priceIncludingVat,
            vatPercentage: 0,
          },
          productName: product.name,
        } satisfies CartRequestCartItem & CartResponseV2CartItem;
      })
      .filter(isTruthy);
  }, [purchaseType, media, photoProduct, videoProduct, albumProductToCharge, albumId]);
  const tempPrice = cartItems.reduce((acc, item) => acc + item.price.amount.amountIncludingVat, 0);

  const {
    mutateAsync: addMultipleCartItemsMutation,
    isPending: addMultipleCartItemsPending,
    error: addMultipleCartItemsError,
    data: addMultipleCartItemsData,
  } = useAddMultipleItemsToCartMutation(undefined, LanguageHelper.currentLocale);
  useEffect(() => {
    if (!isNonEmptyArray(cartItems)) return;

    addMultipleCartItemsMutation({ items: cartItems }).then((response) => {
      trackEcommerceEvent(
        cartItemsToAddToCartGTMEvent(response.cartItems, response.discountItems, response.redeemableValidationResults),
      );
    });
  }, [cartItems, addMultipleCartItemsMutation]);

  const { data: cart } = useCart(addMultipleCartItemsData?.cartGuid);
  const products = useCartItemsFromCartResponse(cart?.cartItems ?? cartItems, cart) ?? [];
  const totalSum = cart?.cartPrice.amount.amountIncludingVat ?? tempPrice;

  // When upgrading to the whole album after having already bought media, add metadata to explain the discount.
  const productsWithUpgradeMetadata =
    purchaseType === "album" && albumUpgradeProduct && previouslyPurchasedMediaCount > 0
      ? products.map((product) =>
          product.productId === albumUpgradeProduct.productId
            ? {
                ...product,
                metadata: [
                  t("rideMediaAlbumUpgradeCheckoutMetaData", { count: previouslyPurchasedMediaCount }),
                  ...(product.metadata ?? []),
                ],
              }
            : product,
        )
      : products;
  return (
    <motion.div
      className={styles.wrapper}
      initial="hidden"
      animate="visible"
      exit="hidden"
      variants={slideRightWhenHiddenVariants(0.5)}
    >
      <GhostButton iconLeftNew="chevron-left" label={t("back")} className={styles.backButton} onClick={onBack} />
      <SummaryList
        category={t("paymentSummary")}
        quantity={t("summaryStepPieces", { count: products.length })}
        preExpanded
        sumPrice={CurrencyHelper.formatToSekWithPossiblePrecision(totalSum)}
      >
        <Cart
          checkoutUrl={eCommerce.shopServicePaymentSlug}
          isDisabled={addMultipleCartItemsPending}
          totalSumInclVat={totalSum}
          products={productsWithUpgradeMetadata}
          hideContinueShopping
          hideGoToCheckout
          hideTotalSum
          hideHeadline
        />
      </SummaryList>
      <p className="body-xxs">{t("rideMediaAlbumPurchaseDisclaimer")}</p>
      {purchaseType === "album" ? (
        <Banner
          type="success"
          heading={t("rideMediaAlbumPurchaseAlbumBannerHeading")}
          paragraph={t("rideMediaAlbumPurchaseAlbumBannerParagraph")}
          border
        />
      ) : (
        <Banner
          type="success"
          heading={t("rideMediaAlbumPurchaseIndividualMediaBannerHeading")}
          paragraph={t("rideMediaAlbumPurchaseIndividualMediaBannerParagraph", {
            count: media.length,
            albumPrice: albumProductToCharge?.glkProduct.priceIncludingVat ?? 0,
          })}
          border
          buttonText={t("rideMediaAlbumPurchaseIndividualMediaBannerCTA")}
          onButtonClick={onSwitchToAlbumPurchase}
          data-testid="ride-media-purchase-individual-media-banner"
        />
      )}
      <SummaryTotal labelId="cartSummary" type="price" price={totalSum} />

      {addMultipleCartItemsPending && <CheckoutLoading />}
      {addMultipleCartItemsError && <CheckoutError />}
      {addMultipleCartItemsData && (
        <ShopServicePayment
          cartId={addMultipleCartItemsData.cartGuid}
          enabled={true}
          shopUrlSlugOverrides={{ confirmationUrl: confirmationPageSlug }}
        />
      )}
    </motion.div>
  );
};
